@startuml

class Bus {
  + LineNumber : string
}

class Trajectory {
  + Status : string
}

class Line {
  + Category : string
}

class TownAuthority {
  + ApprovalStatus : string
}

class ApprovalProcess {
  + Status : string
}

class MENSOUser {
  + HomeAddress : string
  + OfficeAddress : string
  + WorkingHours : string
}

class MENSOCard {
  + CardNumber : string
}

class Trip {
  + Date : date
  + Time : time
}

class Invoice {
  + Month : string
  + TotalAmount : double
  + Discount : double
}

class Customer {
  + Name : string
}

Bus "0..*" -- "1..*" Trajectory : assigned to
Line "1" -- "1..*" Trajectory : groups
Trajectory "1" -- "0..*" ApprovalProcess : undergoes
ApprovalProcess "0..*" -- "1" TownAuthority : handled by
MENSOUser "1" -- "1" MENSOCard : possesses
MENSOUser "1" -- "0..*" Invoice : receives
Customer "1" -- "0..*" Invoice : pays
MENSOUser "1" -- "0..*" Trip : performs
Line "1" -- "0..*" Trip : associated with
Trip "1" -- "1" Invoice : included in

@enduml

